// #8951bb (6a993d67948609c2b98951bb) «פיתוח: מדידת יעדי הפיילוט — נאספת מחוץ למערכת» — «отрицательная» фича:
// в системе НЕТ поля отзыва на отчёте, НЕТ экрана метрик пилота, НЕТ процентов против целей 85/75/10 (F-54, D-03, FL-54).
// Кейсы PIL-001 (отчёт без поля отзыва), PIL-002 (нет экрана метрик), PIL-003 (нет «%» на дашборде и в админке).
// Роли: business (testim), user (משתמש בית העסק), admin (Super Admin) — каждая в своём окне (asUser), по отдельности.
// Допустимо (D-04/D-05, S-19 AC5): «הערה פנימית», счётчики «N סימולציות», квота — это не отзыв и не процент.
// Только чтение → @prod-safe. Админ открывает отчёт с причиной quality_assurance — это пишет строку в רישום גישה (как в ручной проверке).
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { openWithApi } from '../support/api';
import { listCandidates } from '../candidates/hiring-support';

const HASH = '#8951bb · #6a993d67948609c2b98951bb';
const CANDIDATE = process.env.QA_PILOT_REPORT_CANDIDATE || 'QA-4b397a-DISC-2110';
const CANDIDATE_ID = process.env.QA_PILOT_REPORT_CANDIDATE_ID || '81e3f350-36b6-4971-b1de-01c0f16f9998';
const PILOT_BUSINESS = process.env.QA_PILOT_BUSINESS || 'QA-PILOT-1410';
const TESTIM_BUSINESS = 'testim';

/** Слова отзыва/оценки отчёта и метрик пилота (FL-54 «אין טופס משוב במסך הדוח»). */
const FEEDBACK = /משוב|שימושיות|שימושי|טעות מהותית|דירוג|דרגו|הערכת הדוח|האם הדוח|מדדי (ה)?פיילוט|יעדי (ה)?פיילוט/;

/** Подписи элементов управления (кнопки, поля, заголовки, легенды, ссылки) — без текста самого отчёта и транскрипта. */
async function controlLabels(page: Page): Promise<string[]> {
  return page.evaluate(() => {
    const out: string[] = [];
    const sel = 'button, label, legend, h1, h2, h3, h4, a, [role=radio], [role=slider], [role=tab], textarea, input, select';
    for (const e of Array.from(document.querySelectorAll(sel))) {
      if (!(e as HTMLElement).getClientRects().length) continue;
      const t = [e.getAttribute('aria-label'), e.getAttribute('placeholder'), (e as HTMLElement).innerText].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
      if (t) out.push(t.slice(0, 120));
    }
    return out;
  });
}

/** Источник: AC2 «ההערכה … אינה נשמרת כשדה משוב על רשומת הדוח»; треб. 4 «מנגנון משוב מובנה על הדוחות אינו בהיקף». */
async function expectNoFeedbackOnReport(page: Page) {
  await expect(page.getByTestId('report-summary')).toBeVisible({ timeout: 30_000 });
  const labels = await controlLabels(page);
  expect(labels.filter((l) => FEEDBACK.test(l)), 'элементы отзыва/оценки отчёта').toEqual([]);
  await expect(page.locator('input[type=range], [role=slider]'), 'шкала оценки').toHaveCount(0);
  await expect(page.locator('[aria-label*="כוכב"], [data-testid*="feedback"], [data-testid*="rating"]'), 'звёзды/отзыв').toHaveCount(0);
}

/** Источник: AC1 «אינם נאספים בטופס או במסך במערכת»; треб. 4 «פיתוח מסך מדידה … אינו בהיקף». */
async function expectNoMetricsScreen(page: Page) {
  const nav = await page.locator('nav a, aside a, nav button, aside button').evaluateAll((els) =>
    els.filter((e) => (e as HTMLElement).getClientRects().length).map((e) => ((e as HTMLElement).innerText || e.getAttribute('aria-label') || '').trim()),
  );
  expect(nav.length, 'меню не найдено').toBeGreaterThan(0);
  expect(nav.filter((t) => /מדד|מדידה|משוב|פיילוט|BI|אנליטיק|סטטיסטיק/.test(t)), 'пункт меню метрик/отзыва').toEqual([]);
  for (const p of ['/metrics', '/feedback', '/pilot']) {
    await page.goto(p);
    await expect(page.locator('h1'), `${p} должен быть «המסך לא נמצא»`).toHaveText('המסך לא נמצא', { timeout: 30_000 });
  }
}

/** Источник: AC3 «אינו מציג שיעורים מול יעדי 85, 75 ו-10 אחוזים»; D-03 «הדשבורד אינו מערכת BI». */
async function expectNoPercent(page: Page, where: string) {
  const text = await page.evaluate(() => (document.querySelector('main') || document.body).innerText);
  expect(text, `${where}: «%» на экране`).not.toMatch(/%|אחוז/);
}

test.describe(`Метрики пилота вне системы (${HASH})`, () => {
  test(`business: отчёт без поля отзыва; меню без экрана метрик, /metrics /feedback /pilot → «המסך לא נמצא»; дашборд без «%» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const api = await openWithApi(page, '/');
    await expect(page.getByRole('heading', { level: 1, name: /^שלום,/ })).toBeVisible({ timeout: 30_000 });
    await expectNoPercent(page, 'дашборд business');

    const found = (await listCandidates(api)).filter((c) => c.full_name === CANDIDATE);
    expect(found, `кандидат «${CANDIDATE}» не найден (QA-данные 21.10.2026)`).toHaveLength(1);
    await page.goto(`/candidates/${found[0].id}/report`);
    await expectNoFeedbackOnReport(page);

    await page.goto('/');
    await expect(page.getByRole('heading', { level: 1, name: /^שלום,/ })).toBeVisible({ timeout: 30_000 });
    await expectNoMetricsScreen(page);
  });

  test(`user (משתמש בית העסק): готовый отчёт без поля отзыва; меню без экрана метрик, /metrics /feedback /pilot → «המסך לא נמצא»; дашборд без «%» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    const api = await openWithApi(page, '/');
    await expect(page.locator('h1').first()).toBeVisible({ timeout: 30_000 });
    await expectNoPercent(page, 'дашборд user');

    // Отчёт: предпочтительно тот же кандидат; иначе первый кандидат пользователя с готовым отчётом.
    const all = await listCandidates(api);
    let id = all.find((c) => c.full_name === CANDIDATE)?.id;
    if (!id) {
      for (const c of all.slice(0, 40)) {
        const r = await api.rpc('get_candidate_report', { p_candidate_id: c.id, p_reason: null });
        if (!r.ok()) continue;
        const j = await r.json();
        if ((Array.isArray(j) ? j[0] : j)?.report?.status === 'ready') { id = c.id; break; }
      }
    }
    expect(id, 'у user нет ни одного готового отчёта').toBeTruthy();
    await page.goto(`/candidates/${id}/report`);
    await expectNoFeedbackOnReport(page);

    await page.goto('/');
    await expect(page.locator('h1').first()).toBeVisible({ timeout: 30_000 });
    await expectNoMetricsScreen(page);
  });

  test(`admin (Super Admin): отчёт через «תמיכה ותפעול» без поля отзыва; меню без экрана метрик, /metrics /feedback /pilot → «המסך לא נמצא»; «בתי העסק» и карточки ${'QA-PILOT-1410'} / testim без «%» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('admin');
    await page.goto(`/admin/support/candidates/${CANDIDATE_ID}/report?reason=quality_assurance`);
    await expectNoFeedbackOnReport(page);

    await page.goto('/admin/businesses');
    await expect(page.getByRole('heading', { level: 1, name: 'בתי העסק' })).toBeVisible({ timeout: 30_000 });
    await expectNoPercent(page, 'בתי העסק');
    for (const biz of [PILOT_BUSINESS, TESTIM_BUSINESS]) {
      await page.goto('/admin/businesses');
      await page.getByText(biz, { exact: true }).first().click();
      await page.waitForURL(/\/admin\/businesses\/[^/]+$/);
      await expect(page.getByRole('heading', { level: 1, name: biz })).toBeVisible({ timeout: 30_000 });
      await expectNoPercent(page, `карточка ${biz}`);
    }

    await page.goto('/admin/businesses');
    await expect(page.getByRole('heading', { level: 1, name: 'בתי העסק' })).toBeVisible({ timeout: 30_000 });
    await expectNoMetricsScreen(page);
  });
});
